import {VesselProfileRepository,clone} from './vesselProfile.mjs';
import {FUEL_FACTORS,ENGINE_MODEL,SOURCES} from './fuelFactors.mjs';
import {draftToVoyage,parseVoyagePackage,validateVoyage} from './voyageSegments.mjs';
import {FuelAnalysisController} from './coordinator.mjs';
import {ACOUSTIC_CLASSES} from '../voyage/acoustics.mjs';
import {voyageMessage} from '../voyage/messages.mjs';
import {message} from './messages.mjs';

const root=document.getElementById('page-fuel'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=key=>message(key,I18n.language),vt=key=>voyageMessage(key,I18n.language),fmt=(v,d=2)=>typeof v==='number'&&Number.isFinite(v)?new Intl.NumberFormat(I18n.locale,{maximumFractionDigits:d}).format(v):'—',date=v=>v&&Number.isFinite(Date.parse(v))?new Date(v).toLocaleString(I18n.locale,{timeZone:'UTC',dateStyle:'medium',timeStyle:'short'})+' UTC':'—';
let repository;try{repository=new VesselProfileRepository(localStorage);}catch{repository=new VesselProfileRepository({getItem(){throw Error('storage_unavailable');},setItem(){throw Error('storage_unavailable');}});}
let settings=repository.snapshot().settings||{},pane=repository.list().length?'analysis':'profiles',editing=null,dirty=false,notice='',lastDeletedId=null,scienceUnsubscribe=null;
let draft=window.WALegacy.getDraft(),importedReference=settings.referenceRoute||null,hydraRoute=settings.hydraRoute||null;
const controller=new FuelAnalysisController({onChange:()=>{if(pane==='analysis')renderResults();}});
const get=id=>root.querySelector('#'+id);
const button=(action,label,extra='')=>`<button type="button" class="btn secondary compact" data-fuel-action="${action}" ${extra}>${esc(t(label))}</button>`;
const selected=(a,b)=>a===b?' selected':'';
function field(key,label,value='',{type='number',required=false,help=null,min=null,max=null,step='any'}={}){return `<div class="field"><label for="fc-${esc(key)}">${esc(t(label))}</label><input id="fc-${esc(key)}" name="${esc(key)}" type="${type}" value="${esc(value??'')}" ${required?'required':''} ${type==='number'?`step="${step}"`:''} ${min!=null?`min="${min}"`:''} ${max!=null?`max="${max}"`:''} ${type==='text'?'maxlength="180"':''}>${help?`<small>${esc(t(help))}</small>`:''}</div>`;}
function selectField(key,label,value,items){return `<div class="field"><label for="fc-${key}">${esc(t(label))}</label><select id="fc-${key}" name="${key}">${items.map(([v,l])=>`<option value="${v}"${selected(v,value)}>${esc(['USD','EUR','TRY'].includes(l)?l:t(l))}</option>`).join('')}</select></div>`;}
function fuelSelect(key,value,label='fuelId'){return `<div class="field"><label for="fc-${key}">${esc(t(label))}</label><select id="fc-${key}" name="${key}"><option value="">${esc(t('choose'))}</option>${Object.values(FUEL_FACTORS).map(f=>`<option value="${f.id}"${selected(f.id,value)}>${esc(f.name)}${f.consumptionSupported?'':' · '+esc(t('unsupported_fuel_model'))}</option>`).join('')}</select></div>`;}
function blankProfile(){return {name:'',vesselType:'',manufacturerModel:'',imoNumber:'',propulsion:'conventional-diesel',engineType:'',sfocMode:'imo-normalized',fuelId:'',auxiliary:{mode:'unknown'},prices:[]};}
function profileForm(){
  const p=editing||blankProfile(),price=p.prices?.find(x=>x.fuelId===p.fuelId)||{},auxPrice=p.prices?.find(x=>x.fuelId===p.auxiliary?.fuelId)||{},a=p.auxiliary||{mode:'unknown'};
  return `<form id="fc-profile-form"><div class="fuel-editor-heading"><h2>${esc(p.id?t('edit'):t('newProfile'))}</h2>${button('cancel-profile','cancel')}</div><p id="fc-profile-feedback" class="fuel-feedback" role="status"></p><div class="fuel-fields">
  ${field('name','name',p.name,{type:'text',required:true})}${selectField('vesselType','vesselType',p.vesselType,[['','choose'],['cargo','cargo'],['container','container'],['bulk','bulk'],['general-cargo','generalCargo'],['oil-tanker','oilTanker'],['lng-carrier','lngCarrier'],['roro','roro'],['tanker','tanker'],['passenger','passenger'],['fishing','fishing'],['other','other']])}
  ${field('manufacturerModel','manufacturerModel',p.manufacturerModel,{type:'text'})}${field('imoNumber','imoNumber',p.imoNumber,{type:'text'})}
  ${selectField('propulsion','propulsion',p.propulsion,[['conventional-diesel','conventional'],['diesel-electric','dieselElectric'],['hybrid','hybrid'],['multiple','multiple']])}${selectField('engineType','engineType',p.engineType,[['','choose'],['slow-speed-diesel','slow'],['medium-speed-diesel','medium'],['high-speed-diesel','high']])}
  ${field('nominalPowerKw','nominalPowerKw',p.nominalPowerKw,{required:true,min:0,help:'powerHelp'})}${field('referenceSpeedKnots','referenceSpeedKnots',p.referenceSpeedKnots,{required:true,min:0})}
  ${field('referenceLoad','referenceLoad',p.referenceLoad==null?'':p.referenceLoad*100,{required:true,min:0,max:100})}${fuelSelect('fuelId',p.fuelId)}
  ${selectField('sfocMode','sfocMode',p.sfocMode,[['imo-normalized','imoNormalized'],['constant','constant'],['manufacturer-curve','manufacturerCurve']])}
  <div data-fuel-sfoc>${field('sfocGPerKwh','sfocGPerKwh',p.sfocGPerKwh,{min:0,help:'sfocHelp'})}${field('sfocReferenceLoad','sfocReferenceLoad',p.sfocReferenceLoad==null?'':p.sfocReferenceLoad*100,{min:0,max:100})}</div>
  ${field('plannedSpeedKnots','plannedSpeedKnots',p.plannedSpeedKnots,{required:true,min:0})}${field('maxSpeedKnots','maxSpeedKnots',p.maxSpeedKnots,{required:true,min:0})}</div>
  <label class="fuel-check"><input name="displacementModelConfirmed" type="checkbox" ${p.displacementModelConfirmed?'checked':''}><span>${esc(t('confirmModel'))}</span></label>
  <details class="fuel-disclosure" ${p.sfocMode==='manufacturer-curve'?'open':''}><summary>${esc(t('advanced'))}</summary><div class="fuel-fields"><div data-fuel-curve>${field('curveSource','curveSource',p.curveSource,{type:'text'})}<div class="field"><label for="fc-sfocCurve">${esc(t('sfocCurve'))}</label><textarea id="fc-sfocCurve" name="sfocCurve" rows="5" spellcheck="false">${esc(p.sfocCurve?JSON.stringify(p.sfocCurve,null,2):'')}</textarea><small>${esc(t('curveHelp'))}</small></div></div>
  ${field('draftMetres','draftMetres',p.draftMetres,{min:0})}${field('minimumSpeedKnots','minimumSpeedKnots',p.minimumSpeedKnots,{min:0})}${field('lengthMeters','lengthMeters',p.lengthMeters,{min:0})}<div class="field"><label for="fc-noiseClass">${esc(vt('noiseClass'))}</label><select id="fc-noiseClass" name="noiseClass"><option value="">${esc(t('choose'))}</option>${Object.keys(ACOUSTIC_CLASSES).map(c=>`<option value="${esc(c)}" ${selected(c,p.noise?.vesselClass)}>${esc(c)}</option>`).join('')}</select></div><label class="fuel-check"><input name="noiseAcknowledged" type="checkbox" ${p.noise?.scenarioAcknowledged?'checked':''}><span>${esc(vt('noiseAck'))}</span></label>${field('loadingCondition','loadingCondition',p.loadingCondition,{type:'text'})}
  ${field('technicalSource','technicalSource',p.technicalSource,{type:'text'})}<label class="fuel-check"><input type="checkbox" name="verifiedTechnical" ${p.verifiedTechnical?'checked':''}><span>${esc(t('verifiedTechnical'))}</span></label>
  ${field('consumptionRecords','consumptionRecords',p.consumptionRecords,{type:'text',help:'recordsHelp'})}</div>
  <h3>${esc(t('auxiliary'))}</h3>${selectField('auxMode','auxiliary',a.mode,[['unknown','auxUnknown'],['defined','auxDefined'],['none-confirmed','auxNone']])}
  <div class="fuel-fields" data-fuel-aux>${field('auxPower','nominalPowerKw',a.nominalPowerKw,{min:0})}${field('auxLoad','auxLoad',a.load==null?'':a.load*100,{min:0,max:100})}${field('auxSfoc','sfocGPerKwh',a.sfocGPerKwh,{min:0})}${fuelSelect('auxFuel',a.fuelId)}</div>
  <h3>${esc(t('pricing'))}</h3><div class="fuel-fields">${field('price','price',price.perTonne,{min:0})}${selectField('currency','currency',price.currency||'USD',[['USD','USD'],['EUR','EUR'],['TRY','TRY']])}${field('priceDate','priceDate',price.date,{type:'date'})}
  <div data-fuel-aux-price>${field('auxPrice','auxPrice',a.fuelId&&a.fuelId!==p.fuelId?auxPrice.perTonne:'',{min:0})}${field('auxPriceDate','priceDate',a.fuelId&&a.fuelId!==p.fuelId?auxPrice.date:'',{type:'date'})}</div></div></details>
  <div class="fuel-form-actions"><button class="btn primary" type="submit">${esc(t('save'))}</button><small>${esc(t('notIndependent'))}</small></div></form>`;
}
function renderProfiles(){const profiles=repository.list();return `<div class="fuel-profile-layout"><aside class="fuel-profile-list"><div class="fuel-list-heading"><h2>${esc(t('profiles'))}</h2>${button('new-profile','newProfile')}</div>${profiles.length?profiles.map(p=>`<article class="fuel-profile-row ${p.id===repository.selected()?.id?'active':''}"><button data-fuel-select="${esc(p.id)}"><strong>${esc(p.name)}</strong><small>${esc(t(p.vesselType))} · ${esc(t('version'))} ${p.version}</small></button><div>${button('edit-profile','edit',`data-id="${esc(p.id)}"`)}${button('delete-profile','remove',`data-id="${esc(p.id)}"`)}</div></article>`).join(''):`<p>${esc(t('profileEmpty'))}</p>`}</aside><article class="fuel-editor">${profileForm()}</article></div>`;}
function renderAnalysis(){const profiles=repository.list(),profile=repository.selected();return `<div class="fuel-voyage-controls"><div class="field"><label for="fc-profile-select">${esc(t('profiles'))}</label><select id="fc-profile-select"><option value="">${esc(t('choose'))}</option>${profiles.map(p=>`<option value="${esc(p.id)}"${selected(p.id,profile?.id)}>${esc(p.name)} · v${p.version}</option>`).join('')}</select></div>${field('departure','departure',settings.departure||'',{type:'datetime-local',required:true})}${field('preferred','preferred',settings.preferred??'',{min:0,help:'speedFallback'})}${field('arrivalTarget','arrivalTarget',settings.arrivalTarget||'',{type:'datetime-local'})}</div>
  <div class="fuel-route-sources"><div><span>${esc(t('reference'))}</span><strong>${esc(importedReference?.name||t('currentDraft'))}</strong><p>${esc(importedReference?.source.citation||(draft.computedRoute?.status==='found'?window.WARouteText('engine')+' · '+window.WARouteText('limit'):t('draftNotice')))}</p><div>${button('import-reference','importRoute')}${importedReference?button('use-draft','useDraft'):''}<a href="#route" class="fuel-text-link">${esc(t('routePlanner'))} ↗</a></div></div><div><span>${esc(t('hydra'))}</span><strong>${esc(hydraRoute?.name||'—')}</strong><p>${esc(hydraRoute?.source.citation||(window.WAScience?.routingEngines.engines.has('hydra')?t('engineConnected'):t('hydraUnavailable')))}</p><div>${button('import-hydra','importRoute')}${hydraRoute?button('clear-hydra','clearHydra'):''}</div></div></div>
  ${!importedReference&&draft.points.length>1?`<details class="fuel-disclosure"><summary>${esc(t('segmentSpeeds'))}</summary><div class="fuel-speed-list">${draftToVoyage(draft).segments.map((s,i)=>`<label>${esc(t('segment'))} ${i+1}<input type="number" step="any" min="0" data-fuel-speed="${esc(JSON.stringify(s.coordinates))}" value="${esc(settings.speedOverrides?.[JSON.stringify(s.coordinates)]??'')}" aria-label="${esc(t('segment'))} ${i+1} · ${esc(t('speed'))}"><small>${esc(t('segmentSpeedHelp'))}</small></label>`).join('')}</div></details>`:''}
  <div id="fc-results" aria-live="polite"></div>`;}
const metrics=['fuelKg','fuelTonnes','co2Kg','co2Tonnes','fuelKgPerHour','co2KgPerHour','fuelKgPerNm','co2KgPerNm','durationHours','distanceNm','meanSpeedKnots','etaIso','cost'];
function value(result,key){if(result?.status!=='computed')return '—';if(key==='etaIso')return date(result.totals.etaIso);if(key==='cost')return result.cost.amount==null?'—':fmt(result.cost.amount)+' '+result.cost.currency;return fmt(result.totals[key],key==='fuelTonnes'||key==='co2Tonnes'?3:2);}
function segmentTable(result){return `<div class="fuel-table-scroll"><table class="fuel-data-table"><thead><tr>${['segment','distanceNm','speed','durationHours','power','load','sfocGPerKwh','mainFuel','auxFuel','co2Kg'].map(k=>`<th scope="col">${esc(t(k))}</th>`).join('')}</tr></thead><tbody>${result.segments.map((s,i)=>`<tr><th scope="row">${i+1}</th>${[s.distanceNm,s.speedKnots,s.durationHours,s.powerKw,s.load*100,s.sfocGPerKwh,s.mainFuelKg,s.auxiliaryFuelKg,s.co2Kg].map(n=>`<td>${fmt(n)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function describeIssues(result){return result?.issues?.map(i=>`${i.field!=='voyage'?t(i.field.split('.').at(-1))+': ':''}${t(i.code)}`).join(' · ')||'';}
function comparisonHTML(comparison){if(comparison?.status!=='computed')return `<p class="fuel-state-note">${esc(t(comparison?.reason||'two_routes_required'))}</p>`;const c=comparison,summary=c.co2.percent==null?t('unavailable'):c.co2.percent===0?t('resultSame'):t(c.co2.percent<0?'resultReduction':'resultIncrease')+' '+fmt(Math.abs(c.co2.percent))+'%';return `<div class="fuel-comparison-summary"><strong>${esc(summary)}</strong><p>${esc(t(c.scope==='main-engine-only'?'mainOnly':'mainAux'))}</p></div><div class="fuel-table-scroll"><table class="fuel-data-table"><thead><tr><th>${esc(t('metric'))}</th><th>${esc(t('changes'))} (%)</th><th>${esc(t('changes'))}</th></tr></thead><tbody>${[['fuel','savingFuel','extraFuel','kg'],['co2','avoidedCo2','extraCo2','kg'],['cost','savingCost','extraCost',c.currency||'']].map(([key,saving,extra,unit])=>`<tr><th>${esc(t(c[key].saving<0?extra:saving))}</th><td>${c[key].percent==null?'—':(c[key].percent>0?'+':'')+fmt(c[key].percent)+'%'}</td><td>${c[key].saving==null?'—':fmt(Math.abs(c[key].saving))+' '+esc(unit)}</td></tr>`).join('')}</tbody></table></div>`;}
function qualityLabel(key){if(key.startsWith('auxiliary.'))return t('auxiliary')+' · '+t(key.split('.').at(-1)==='load'?'auxLoad':key.split('.').at(-1)==='mode'?'auxiliary':key.split('.').at(-1));if(key.startsWith('prices.'))return t('pricing')+' · '+(FUEL_FACTORS[key.split('.')[1]]?.name||'')+' · '+t({perTonne:'price',date:'priceDate',currency:'currency'}[key.split('.')[2]]);return t(key);}
function transparency(result){const p=result.provenance,profile=p.inputs.profile;return `<details class="fuel-disclosure"><summary>${esc(t('transparency'))}</summary><dl class="fuel-audit"><div><dt>${esc(t('profiles'))}</dt><dd>${esc(profile.name)} · v${esc(profile.version??'—')}</dd></div><div><dt>${esc(t('computedAt'))}</dt><dd>${esc(date(p.calculatedAt))}</dd></div><div><dt>${esc(t('model'))}</dt><dd>${esc(p.model.id)} / ${esc(p.model.version)} · ${esc(profile.sfocMode)}</dd></div><div><dt>SHA-256</dt><dd class="fuel-hash">${esc(p.inputSha256)}</dd></div><div><dt>CO₂ CF</dt><dd>${esc(p.factorVersion)}</dd></div></dl><p>${esc(t('scopeNote'))}</p><p>${esc(t('costNote'))}</p><ul class="fuel-sources">${Object.values(SOURCES).map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a> · ${esc(s.sections)}</li>`).join('')}</ul><div class="fuel-table-scroll"><table class="fuel-data-table"><thead><tr><th>${esc(t('metric'))}</th><th>${esc(t('quality'))}</th><th>${esc(t('source'))}</th></tr></thead><tbody>${Object.entries(p.fieldQuality).map(([key,q])=>`<tr><th>${esc(qualityLabel(key))}</th><td>${esc(t({'user-entered':'userEntered','verified-technical':'verified','literature-assumption':'literature','algorithm-calculated':'calculated',missing:'missing'}[q.kind]))}</td><td>${esc(q.source||'—')}</td></tr>`).join('')}</tbody></table></div><p><a class="fuel-text-link" href="fuel/methodology.md" target="_blank">${esc(t('methodLink'))} ↗</a></p></details>`;}
function resultHTML(state,snapshot=false){
  const {reference:a,hydra:b,comparison}=state,computed=[a,b].filter(r=>r?.status==='computed');
  if(!computed.length){const issues=[describeIssues(a),describeIssues(b)].filter(Boolean);return `<div class="fuel-empty"><span>—</span><h2>${esc(t(state.status==='calculating'?'calculating':'totals'))}</h2><p>${esc(state.reason?t(state.reason):issues.join(' · ')||t('noResults'))}</p>${!repository.selected()?button('profiles','newProfile'):''}</div>`;}
  const scope=computed[0].scope,refLabel=a?.route?.source.kind==='legacy-waypoints'?t('currentDraft'):t('reference');
  return `<div class="fuel-results-heading"><div><h2>${esc(t('totals'))}</h2><p>${esc(t(scope==='main-engine-only'?'mainOnly':'mainAux'))}</p></div>${snapshot?'':`<div>${button('save-result','saveResult')}${button('export-result','exportResult')}</div>`}</div>${comparisonHTML(comparison)}
  ${[a,b].filter(r=>r?.status==='blocked').map(r=>`<p class="fuel-error">${esc(describeIssues(r))}</p>`).join('')}
  <div class="fuel-table-scroll"><table class="fuel-data-table fuel-comparison-table"><thead><tr><th scope="col">${esc(t('metric'))}</th><th scope="col">${esc(refLabel)}</th><th scope="col">${esc(t('hydra'))}</th></tr></thead><tbody>${metrics.map(key=>`<tr><th scope="row">${esc(t(key))}</th><td>${esc(value(a,key))}</td><td>${esc(value(b,key))}</td></tr>`).join('')}</tbody></table></div>
  ${computed.map(r=>`<section class="fuel-result-detail"><h3>${esc(r.route.role==='hydra'?t('hydra'):refLabel)}</h3><ul class="fuel-warnings">${[...r.warnings,...(r.totals.arrivalTargetMet===false?['missedTarget']:[])].map(w=>`<li>${esc(t(w))}</li>`).join('')}</ul><details class="fuel-disclosure"><summary>${esc(t('segments'))} · ${r.segments.length}</summary>${segmentTable(r)}</details>${transparency(r)}</section>`).join('')}`;
}
function renderResults(){const container=get('fc-results');if(container)container.innerHTML=resultHTML(controller.state);}
function renderHistory(){const history=repository.snapshot().calculations;return `<div class="fuel-history">${history.length?history.map(item=>{const result=item.reference?.status==='computed'?item.reference:item.hydra,p=result?.provenance?.inputs?.profile;return `<details class="fuel-history-item"><summary><strong>${esc(p?.name||'—')}</strong><span>${esc(date(item.savedAt))} · v${esc(p?.version??'—')}</span></summary><p class="fuel-state-note">${esc(t('snapshotNote'))}</p>${button('export-saved','exportResult',`data-id="${esc(item.id)}"`)}${resultHTML(item,true)}</details>`;}).join(''):`<div class="fuel-empty"><span>—</span><p>${esc(t('noHistory'))}</p></div>`}</div>`;}
function render(){root.innerHTML=`<div class="fuel-page-heading"><div><span class="fuel-product-label">Fuel & Carbon Intelligence</span><h1>${esc(t('title'))}</h1><p>${esc(t('intro'))}</p></div><a href="#route" class="fuel-text-link">${esc(t('routePlanner'))} ↗</a></div><nav class="fuel-route-nav" aria-label="${esc(t('routePlanner'))}"><a href="#analysis">${esc(t('positionAnalysis'))}</a><a href="#route">${esc(t('routePlanner'))}</a><a href="#fuel" aria-current="page">${esc(t('title'))}</a></nav><a class="voyage-link btn secondary" href="#voyage">${esc(vt('title'))} ↗</a><div class="fuel-local-note"><p>${esc(t('local'))}</p>${button('backup','backup')}</div><div class="fuel-tabs" role="tablist">${['analysis','profiles','history'].map(p=>`<button type="button" role="tab" data-fuel-pane="${p}" aria-selected="${p===pane}">${esc(t(p))}${p==='profiles'?` <span>${repository.list().length}</span>`:''}</button>`).join('')}</div><p class="fuel-feedback ${repository.loadError?'fuel-error':''}" id="fc-notice" role="status">${esc(repository.loadError?t('damaged_fuel_storage'):notice)}${lastDeletedId?' '+button('undo-delete','undo'):''}</p><div id="fc-pane" role="tabpanel">${pane==='profiles'?renderProfiles():pane==='history'?renderHistory():renderAnalysis()}</div><p class="fuel-scope-footer">${esc(t('scopeNote'))}</p><dialog id="fc-import-dialog" class="product-dialog fuel-import-dialog"><form id="fc-import-form"><div class="fuel-editor-heading"><h2 id="fc-import-title">${esc(t('importRoute'))}</h2>${button('close-import','cancel')}</div><p>${esc(t('importHelp'))}</p><input type="hidden" name="role" value="reference"><div class="field"><label for="fc-import-text">${esc(t('importJson'))}</label><textarea id="fc-import-text" name="json" rows="12" required spellcheck="false"></textarea></div><input type="file" id="fc-import-file" accept=".json,application/json" hidden>${button('read-file','chooseFile')}<label class="fuel-check"><input name="attested" type="checkbox" required><span>${esc(t('importConfirm'))}</span></label><p id="fc-import-feedback" class="fuel-error" role="status"></p><div class="fuel-form-actions"><button type="submit" class="btn primary">${esc(t('importAction'))}</button><a class="fuel-text-link" href="fuel/methodology.md" target="_blank">${esc(t('methodLink'))} ↗</a></div></form></dialog>`;
  if(pane==='analysis')renderResults();if(pane==='profiles')profileVisibility();
}
function profileVisibility(){const f=get('fc-profile-form');if(!f)return;f.querySelector('[data-fuel-curve]').hidden=f.elements.sfocMode.value!=='manufacturer-curve';f.querySelector('[data-fuel-sfoc]').hidden=f.elements.sfocMode.value==='manufacturer-curve';f.querySelector('[data-fuel-aux]').hidden=f.elements.auxMode.value!=='defined';f.querySelector('[data-fuel-aux-price]').hidden=f.elements.auxMode.value!=='defined'||!f.elements.auxFuel.value||f.elements.auxFuel.value===f.elements.fuelId.value;}
function setNotice(text){notice=text;const n=get('fc-notice');if(n)n.textContent=text;}
function saveSettings(patch){settings={...settings,...patch};try{repository.settings(patch);return true;}catch{setNotice(t('error'));return false;}}
const utc=value=>value&&Number.isFinite(Date.parse(value+'Z'))?new Date(value+'Z').toISOString():null;
function recalculate(){
  if(dirty){controller.invalidate('unsaved_profile');return;}
  const profile=repository.selected();if(!profile){controller.invalidate('profileNeeded');return;}
  const reference=importedReference||draftToVoyage(draft,{speedOverrides:settings.speedOverrides}),inputs={profile,reference,hydra:hydraRoute,departureIso:utc(settings.departure),arrivalTargetIso:settings.arrivalTarget?utc(settings.arrivalTarget)||'invalid':null,preferredSpeedKnots:settings.preferred??profile.plannedSpeedKnots};
  controller.update(inputs);
  window.dispatchEvent(new CustomEvent('walerter:fuel-inputs-changed',{detail:clone(inputs)}));
}
function profileFromForm(form){
  const s=name=>form.elements[name].value.trim(),n=name=>s(name)===''?null:Number(s(name)),fraction=name=>n(name)==null?null:n(name)/100;
  const p={...(editing||{}),name:s('name'),vesselType:s('vesselType'),manufacturerModel:s('manufacturerModel'),imoNumber:s('imoNumber'),propulsion:s('propulsion'),engineType:s('engineType'),nominalPowerKw:n('nominalPowerKw'),referenceSpeedKnots:n('referenceSpeedKnots'),referenceLoad:fraction('referenceLoad'),sfocMode:s('sfocMode'),sfocGPerKwh:n('sfocGPerKwh'),sfocReferenceLoad:fraction('sfocReferenceLoad'),fuelId:s('fuelId'),plannedSpeedKnots:n('plannedSpeedKnots'),maxSpeedKnots:n('maxSpeedKnots'),displacementModelConfirmed:form.elements.displacementModelConfirmed.checked,draftMetres:n('draftMetres'),minimumSpeedKnots:n('minimumSpeedKnots'),lengthMeters:n('lengthMeters'),noise:{vesselClass:s('noiseClass'),scenarioAcknowledged:form.elements.noiseAcknowledged.checked},loadingCondition:s('loadingCondition'),technicalSource:s('technicalSource'),verifiedTechnical:form.elements.verifiedTechnical.checked,consumptionRecords:s('consumptionRecords'),curveSource:s('curveSource'),sfocCurve:null,auxiliary:{mode:s('auxMode')},prices:[],fieldQuality:{}};
  if(p.sfocMode==='manufacturer-curve'){try{p.sfocCurve=JSON.parse(s('sfocCurve'));}catch{const e=Error('invalid_curve');e.issues=[{field:'sfocCurve',code:'invalid_curve'}];throw e;}}
  if(p.auxiliary.mode==='defined')p.auxiliary={mode:'defined',nominalPowerKw:n('auxPower'),load:fraction('auxLoad'),sfocGPerKwh:n('auxSfoc'),fuelId:s('auxFuel')};
  if(n('price')!=null||s('priceDate'))p.prices.push({fuelId:p.fuelId,perTonne:n('price'),currency:s('currency'),date:s('priceDate')});
  if(p.auxiliary.mode==='defined'&&p.auxiliary.fuelId!==p.fuelId&&(n('auxPrice')!=null||s('auxPriceDate')))p.prices.push({fuelId:p.auxiliary.fuelId,perTonne:n('auxPrice'),currency:s('currency'),date:s('auxPriceDate')});
  if(p.verifiedTechnical){for(const key of ['nominalPowerKw','referenceSpeedKnots','referenceLoad','sfocGPerKwh','sfocReferenceLoad','engineType','auxiliary','sfocCurve'])if(p[key]!=null)p.fieldQuality[key]={kind:'verified-technical',source:p.technicalSource};}
  return p;
}
function download(data,name){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportCalculation(data){download({format:'w-alerter-fuel-report',version:1,exportedAt:new Date().toISOString(),...clone(data)},'w-alerter-fuel-carbon.json');}
root.addEventListener('click',e=>{
  const tab=e.target.closest('[data-fuel-pane]');if(tab){pane=tab.dataset.fuelPane;if(pane!=='profiles'&&dirty){editing=null;dirty=false;recalculate();}render();return;}
  const choose=e.target.closest('[data-fuel-select]');if(choose){repository.select(choose.dataset.fuelSelect);dirty=false;editing=null;pane='analysis';render();recalculate();return;}
  const action=e.target.closest('[data-fuel-action]');if(!action)return;
  try{switch(action.dataset.fuelAction){
    case 'profiles':pane='profiles';render();break;
    case 'new-profile':pane='profiles';editing=blankProfile();dirty=true;controller.invalidate('unsaved_profile');render();break;
    case 'edit-profile':pane='profiles';editing=repository.list().find(p=>p.id===action.dataset.id);dirty=true;controller.invalidate('unsaved_profile');render();break;
    case 'cancel-profile':dirty=false;editing=null;pane=repository.list().length?'analysis':'profiles';render();recalculate();break;
    case 'delete-profile':lastDeletedId=action.dataset.id;repository.remove(lastDeletedId);editing=null;dirty=false;notice=t('profileDeleted');render();recalculate();break;
    case 'undo-delete':repository.restore(lastDeletedId);lastDeletedId=null;notice='';render();recalculate();break;
    case 'use-draft':importedReference=null;saveSettings({referenceRoute:null});render();recalculate();break;
    case 'clear-hydra':hydraRoute=null;saveSettings({hydraRoute:null});render();recalculate();break;
    case 'import-reference':case 'import-hydra':{const role=action.dataset.fuelAction==='import-hydra'?'hydra':'reference',f=get('fc-import-form');f.reset();f.elements.role.value=role;get('fc-import-title').textContent=t(role);get('fc-import-feedback').textContent='';get('fc-import-dialog').showModal();break;}
    case 'close-import':get('fc-import-dialog').close();break;
    case 'read-file':get('fc-import-file').click();break;
    case 'save-result':if([controller.state.reference,controller.state.hydra].some(r=>r?.status==='computed')){repository.saveCalculation(controller.state);setNotice(t('savedResult'));}break;
    case 'export-result':exportCalculation(controller.state);break;
    case 'export-saved':exportCalculation(repository.snapshot().calculations.find(r=>r.id===action.dataset.id));break;
    case 'backup':download(repository.loadError?localStorage.getItem(repository.key)||'':repository.snapshot(),'w-alerter-vessels-and-calculations.json');break;
  }}catch(error){setNotice(t(error.message));}
});
root.addEventListener('submit',e=>{
  e.preventDefault();const form=e.target;
  if(form.id==='fc-profile-form')try{const p=profileFromForm(form),saved=repository.save(p);editing=clone(saved);dirty=false;pane='analysis';notice=t('profileSaved');lastDeletedId=null;render();recalculate();}catch(error){get('fc-profile-feedback').textContent=error.issues?.map(i=>qualityLabel(i.field)+': '+t(i.code)).join(' · ')||t(error.message);}
  if(form.id==='fc-import-form')try{if(!form.elements.attested.checked)throw Error('route_verification_required');const role=form.elements.role.value,route=parseVoyagePackage(form.elements.json.value,role);if(role==='hydra'){route.source.kind='hydra-import';hydraRoute=route;saveSettings({hydraRoute:route});}else{importedReference=route;saveSettings({referenceRoute:route});}get('fc-import-dialog').close();notice=t('imported');render();recalculate();}catch(error){get('fc-import-feedback').textContent=t(error.message);}
});
root.addEventListener('input',e=>{
  if(e.target.closest('#fc-profile-form')){dirty=true;controller.invalidate('unsaved_profile');profileVisibility();return;}
  if(e.target.matches('[data-fuel-speed]')){const v=e.target.value===''?null:Number(e.target.value),overrides={...(settings.speedOverrides||{})};if(v===null)delete overrides[e.target.dataset.fuelSpeed];else overrides[e.target.dataset.fuelSpeed]=v;saveSettings({speedOverrides:overrides});recalculate();return;}
  const key={'fc-departure':'departure','fc-arrivalTarget':'arrivalTarget','fc-preferred':'preferred'}[e.target.id];if(key){saveSettings({[key]:key==='preferred'?(e.target.value===''?null:Number(e.target.value)):e.target.value});recalculate();}
});
root.addEventListener('change',async e=>{
  if(e.target.id==='fc-profile-select'){try{repository.select(e.target.value);dirty=false;recalculate();}catch{controller.invalidate('profileNeeded');}}
  if(e.target.id==='fc-import-file'&&e.target.files[0])try{const file=e.target.files[0];if(file.size>5*1024*1024)throw Error('invalid_route_package');get('fc-import-text').value=await file.text();}catch(error){get('fc-import-feedback').textContent=t(error.message);}
});
const updateDraftGeometry=e=>{draft=clone(e.detail);if(hydraRoute?.source.kind==='hydra-engine'){hydraRoute=null;saveSettings({hydraRoute:null});}controller.invalidate();if(pane==='analysis'&&document.body.dataset.page==='fuel')render();recalculate();};window.addEventListener('walerter:routechange',updateDraftGeometry);window.addEventListener('walerter:routeplanned',updateDraftGeometry);
window.addEventListener('languagechange',()=>{const form=get('fc-profile-form'),values=form?[...form.elements].filter(e=>e.name).map(e=>({name:e.name,value:e.value,checked:e.checked,type:e.type})):null,advanced=form?.querySelector('details')?.open;notice='';render();if(values&&get('fc-profile-form')){for(const item of values){const el=get('fc-profile-form').elements[item.name];if(el){el.value=item.value;if(item.type==='checkbox')el.checked=item.checked;}}get('fc-profile-form').querySelector('details').open=advanced;profileVisibility();}});
window.addEventListener('walerter:pagechange',e=>{if(e.detail.page==='fuel'){render();recalculate();}});
function acceptHydraOutput(event){
  if(event.id!=='hydra'||event.output?.status!=='computed')return;
  controller.invalidate();
  try{const raw=event.output.result?.route||event.output.result,route=clone(raw);route.role='hydra';route.source={...route.source,kind:'hydra-engine',engineVersion:event.engineVersion,citation:typeof event.provenance==='string'?event.provenance:JSON.stringify(event.provenance),verification:'engine-reviewed'};route.departureIso=route.departureIso||event.context?.departureIso;if(!route.departureIso)throw Error('departure_required');validateVoyage(route);hydraRoute=route;saveSettings({hydraRoute:route});if(pane==='analysis')render();recalculate();}catch(error){hydraRoute=null;saveSettings({hydraRoute:null});controller.invalidate(error.message);}
}
function bindRouting(){if(scienceUnsubscribe||!window.WAScience?.routingEngines.subscribe)return;scienceUnsubscribe=window.WAScience.routingEngines.subscribe(acceptHydraOutput);}
window.addEventListener('load',bindRouting,{once:true});bindRouting();
window.WAFuel=Object.freeze({repository,controller,evaluateInputs:inputs=>controller.update(inputs),current:()=>clone(controller.state),model:ENGINE_MODEL,routePackageFormat:'w-alerter-voyage/1'});
render();recalculate();
